const searchPersons = `-- name: SearchPersons :many
SELECT p.id, p.code, p.display_name, p.created_at, p.updated_at, las.last_active
FROM openfaithmap.identity_persons p
LEFT JOIN openfaithmap.identity_accounts a ON a.person_id = p.id AND a.deleted_at IS NULL
LEFT JOIN (
	SELECT account_id, MAX(last_seen_at) AS last_active
	FROM openfaithmap.identity_sessions
	GROUP BY account_id
) las ON las.account_id = a.id
WHERE p.deleted_at IS NULL
  AND ($1::text = '' OR p.display_name ILIKE '%' || $1::text || '%' OR p.code ILIKE '%' || $1::text || '%')
ORDER BY p.display_name
LIMIT $2
`

type SearchPersonsParams struct {
	Query      string
	LimitCount int32
}

type SearchPersonsRow struct {
	ID          string
	Code        pgtype.Text
	DisplayName string
	CreatedAt   time.Time
	UpdatedAt   time.Time
	LastActive  interface{}
}

func (q *Queries) SearchPersons(ctx context.Context, arg SearchPersonsParams) ([]SearchPersonsRow, error) {
	rows, err := q.db.Query(ctx, searchPersons, arg.Query, arg.LimitCount)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchPersonsRow
	for rows.Next() {
		var i SearchPersonsRow
		if err := rows.Scan(
			&i.ID,
			&i.Code,
			&i.DisplayName,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.LastActive,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

